import sys

def main():
    try:
        line = sys.stdin.read().strip()
        if not line:
            return
        n = int(line)
    except ValueError:
        return

    if n == 1:
        print("YES")
        print(1)
        return

    if n == 4:
        print("NO")
        return

    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    p = 2
    while p * p <= n:
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1

    if not is_prime[n]:
        print("NO")
        return

    print("YES")
    res = []
    res.append(1)
    if n > 1:
        res.append(n)

    used = {1, n}
    current = 1
    for target in range(1, n):
        if target == 1:
            continue

        if target == n - 1:
            needed = n
        else:
            inv = pow(current, -1, n)
            needed = (target * inv) % n
            if needed == 0:
                needed = n

        if needed in used:
            continue

        used.add(needed)
        res.append(needed)
        current = (current * needed) % n

    if len(res) != n:
        print("NO")
        return

    for x in res:
        print(x)

if __name__ == "__main__":
    main()
